function useBotSync(botId:string){
  const queryClient=useQueryClient(); const [state,setState]=useState<"live"|"reconnecting"|"polling">("reconnecting");
  useEffect(()=>{
    let socket:WebSocket|undefined; let retry:ReturnType<typeof setTimeout>|undefined; let cancelled=false; let attempt=0;
    const connect=()=>{
      if(cancelled)return;
      const protocol=window.location.protocol==="https:"?"wss:":"ws:";
      socket=new WebSocket(`${protocol}//${window.location.host}/api/v1/ws/${botId}`);
      socket.onopen=()=>{attempt=0;setState("live")};
      socket.onmessage=()=>{queryClient.invalidateQueries({queryKey:["bots"]});queryClient.invalidateQueries({queryKey:["dashboard",botId]})};
      socket.onerror=()=>socket?.close();
      socket.onclose=()=>{if(cancelled)return;setState(attempt>=2?"polling":"reconnecting");retry=setTimeout(connect,Math.min(1000*2**attempt++,15000))};
    };
    connect(); return()=>{cancelled=true;if(retry)clearTimeout(retry);socket?.close()};
  },[botId,queryClient]);
  return state;
}

const authSchema=z.object({email:z.email("Informe um e-mail válido"),password:z.string().min(12,"Use pelo menos 12 caracteres")});
const botSchema=z.object({name:z.string().min(2),capital:z.number().min(100,"O valor inicial é R$ 100"),symbols:z.array(z.string()).min(1),risk_profile:z.enum(["CONSERVATIVE","MODERATE"])});
type AuthForm=z.infer<typeof authSchema>; type BotForm=z.infer<typeof botSchema>;
const money=(value:string|number|undefined=0)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value));
const quantity=(value:string,symbol:string)=>Number(value).toLocaleString("pt-BR",{minimumFractionDigits:0,maximumFractionDigits:symbol.startsWith("SOL")?6:8});
const dateTime=(value:string)=>new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"}).format(new Date(value));
const card="rounded-2xl border border-white/[.08] bg-[#101522]/90 shadow-[0_16px_50px_rgba(0,0,0,.18)] backdrop-blur";

function Logo({compact=false}:{compact?:boolean}){return <div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-[14px] bg-gradient-to-br from-violet-500 to-cyan-400 shadow-lg shadow-violet-950/40"><span className="text-xl font-black text-white">B</span></div>{!compact&&<div><p className="text-[17px] font-bold tracking-tight text-white">Bitty</p><p className="text-[11px] text-slate-500">Automação pessoal</p></div>}</div>}

function AuthScreen(){
  const queryClient=useQueryClient(); const [mode,setMode]=useState<"login"|"register">("login"); const form=useForm<AuthForm>({resolver:zodResolver(authSchema)});
  const authentication=useMutation({mutationFn:(values:AuthForm)=>api(mode==="login"?"/auth/login":"/auth/register",{method:"POST",body:JSON.stringify(values)}),onSuccess:()=>queryClient.invalidateQueries({queryKey:["me"]})});
  const error=authentication.error?.message==="Invalid credentials"?"E-mail ou senha incorretos.":authentication.error?.message;
  return <main className="bitty-grid relative min-h-dvh overflow-hidden bg-[#080b16] p-5 lg:grid lg:grid-cols-[1.05fr_.95fr] lg:p-0">
    <div className="pointer-events-none absolute -left-24 top-1/4 size-80 rounded-full bg-violet-600/15 blur-[100px]"/><div className="pointer-events-none absolute right-0 top-0 size-80 rounded-full bg-cyan-500/10 blur-[110px]"/>
    <section className="relative hidden border-r border-white/[.06] p-12 lg:flex lg:flex-col lg:justify-between xl:p-16"><Logo/><div className="max-w-xl"><Badge tone="neutral"><Sparkles className="mr-1.5 size-3"/> CONTROLE EM PRIMEIRO LUGAR</Badge><h1 className="mt-7 text-balance text-5xl font-semibold leading-[1.08] tracking-tight">Seu bot de cripto.<br/><span className="bg-gradient-to-r from-violet-300 to-cyan-300 bg-clip-text text-transparent">Claro, seguro e em reais.</span></h1><p className="mt-5 max-w-lg text-lg leading-8 text-slate-400">Mercado ao vivo, decisões auditáveis e limites que interrompem a operação quando algo não parece certo.</p><div className="mt-10 grid gap-3 sm:grid-cols-2">{[[ShieldCheck,"Proteções ativas","Cada ordem passa por regras determinísticas."],[Radio,"Preços reais","Cotações públicas do Mercado Bitcoin."],[Activity,"Tudo visível","Patrimônio, posições e ordens em um lugar."],[Zap,"Falha segura","Sem dados confiáveis, nenhuma ordem é enviada."]].map(([Icon,title,body])=><div className="rounded-2xl border border-white/[.07] bg-white/[.035] p-4" key={String(title)}><Icon className="size-5 text-violet-300"/><p className="mt-3 text-sm font-semibold">{String(title)}</p><p className="mt-1 text-sm leading-6 text-slate-500">{String(body)}</p></div>)}</div></div><p className="text-xs text-slate-600">Uso pessoal · Trading real permanece bloqueado nesta etapa.</p></section>
    <section className="relative flex min-h-[calc(100dvh-2.5rem)] items-center justify-center"><div className="w-full max-w-md"><div className="mb-8 lg:hidden"><Logo/></div><div className={cn(card,"p-6 sm:p-8")}><Badge>{mode==="login"?"ACESSO SEGURO":"NOVA CONTA"}</Badge><h2 className="mt-5 text-3xl font-semibold tracking-tight">{mode==="login"?"Que bom ter você aqui.":"Comece com R$ 100 virtuais."}</h2><p className="mt-2 text-sm leading-6 text-slate-400">{mode==="login"?"Entre para acompanhar o Bitty no notebook e no celular.":"Primeiro validamos tudo em Paper Trading."}</p><form className="mt-7 space-y-5" onSubmit={form.handleSubmit(values=>authentication.mutate(values))}><label className="block text-sm font-medium text-slate-300">E-mail<Input className="mt-2" type="email" autoComplete="email" placeholder="voce@exemplo.com" {...form.register("email")}/>{form.formState.errors.email&&<span className="mt-1.5 block text-xs text-red-400">{form.formState.errors.email.message}</span>}</label><label className="block text-sm font-medium text-slate-300">Senha<Input className="mt-2" type="password" autoComplete={mode==="login"?"current-password":"new-password"} placeholder="Mínimo de 12 caracteres" {...form.register("password")}/>{form.formState.errors.password&&<span className="mt-1.5 block text-xs text-red-400">{form.formState.errors.password.message}</span>}</label>{error&&<div role="alert" className="rounded-xl border border-red-500/20 bg-red-500/10 p-3 text-sm text-red-300">{error}</div>}<Button className="w-full" disabled={authentication.isPending}>{authentication.isPending?"Processando…":mode==="login"?"Entrar no Bitty":"Criar minha conta"}<ChevronRight className="ml-2 size-4"/></Button></form><div className="mt-6 border-t border-white/[.07] pt-6 text-center"><button className="text-sm text-slate-400 hover:text-white" onClick={()=>{setMode(mode==="login"?"register":"login");authentication.reset()}}>{mode==="login"?"Primeiro acesso? Criar conta":"Já tenho conta. Entrar"}</button></div></div></div></section>
  </main>;
}

function Onboarding(){
  const queryClient=useQueryClient(); const form=useForm<BotForm>({resolver:zodResolver(botSchema),defaultValues:{name:"Bitty Auto",capital:100,symbols:["BTC/BRL","ETH/BRL"],risk_profile:"CONSERVATIVE"}}); const selected=useWatch({control:form.control,name:"symbols"}); const risk=useWatch({control:form.control,name:"risk_profile"});
  const create=useMutation({mutationFn:(values:BotForm)=>api("/bots",{method:"POST",body:JSON.stringify(values)}),onSuccess:()=>queryClient.invalidateQueries({queryKey:["bots"]})}); const toggle=(symbol:string)=>form.setValue("symbols",selected.includes(symbol)?selected.filter(item=>item!==symbol):[...selected,symbol],{shouldValidate:true});
  return <main className="bitty-grid min-h-dvh bg-[#080b16] p-5 sm:p-8"><div className="mx-auto max-w-3xl"><Logo/><section className={cn(card,"mt-10 p-6 sm:p-8")}><div className="flex items-start justify-between gap-4"><div><Badge>PAPER TRADING</Badge><h1 className="mt-4 text-3xl font-semibold tracking-tight">Configure seu Bitty</h1><p className="mt-2 text-slate-400">Comece com R$ 100 virtuais e regras conservadoras.</p></div><ShieldCheck className="size-8 text-violet-300"/></div><form className="mt-8 space-y-8" onSubmit={form.handleSubmit(values=>create.mutate(values))}><div className="grid gap-5 sm:grid-cols-2"><label className="text-sm font-medium">Nome do bot<Input className="mt-2" {...form.register("name")}/></label><label className="text-sm font-medium">Valor inicial<Input className="mt-2 tabular-nums" type="number" min="100" step="10" {...form.register("capital",{valueAsNumber:true})}/><span className="mt-1.5 block text-xs text-slate-500">Mínimo: R$ 100,00</span></label></div><fieldset><legend className="text-sm font-medium">Ativos em reais</legend><div className="mt-3 grid grid-cols-3 gap-3">{["BTC/BRL","ETH/BRL","SOL/BRL"].map(symbol=><button type="button" key={symbol} onClick={()=>toggle(symbol)} className={cn("flex min-h-14 items-center justify-between rounded-xl border px-4 text-sm font-semibold transition",selected.includes(symbol)?"border-violet-400/50 bg-violet-500/10 text-violet-200":"border-white/[.08] bg-black/20 text-slate-400")}><span>{symbol.split("/")[0]}</span>{selected.includes(symbol)&&<Check className="size-4"/>}</button>)}</div></fieldset><fieldset><legend className="text-sm font-medium">Perfil de risco</legend><div className="mt-3 grid gap-3 sm:grid-cols-2">{[["CONSERVATIVE","Conservador","3% por ordem · 10% por ativo"],["MODERATE","Moderado","5% por ordem · 15% por ativo"]].map(([value,title,body])=><label className={cn("cursor-pointer rounded-xl border p-4",risk===value?"border-violet-400/50 bg-violet-500/10":"border-white/[.08] bg-black/20")} key={value}><input className="sr-only" type="radio" value={value} {...form.register("risk_profile")}/><span className="font-semibold">{title}</span><span className="mt-1 block text-sm text-slate-500">{body}</span></label>)}</div></fieldset>{create.error&&<div role="alert" className="rounded-xl border border-red-500/20 bg-red-500/10 p-3 text-sm text-red-300">{create.error.message}</div>}<div className="flex flex-wrap items-center justify-between gap-4 border-t border-white/[.07] pt-6"><p className="max-w-sm text-xs leading-5 text-slate-500">Nenhum dinheiro real será movimentado.</p><Button disabled={create.isPending}>{create.isPending?"Criando…":"Criar Bitty"}<ChevronRight className="ml-2 size-4"/></Button></div></form></section></div></main>;
}

function MarketCard({row,status}:{row?:Market;status:string}){const asset=row?.symbol.split("/")[0]||"—";return <div className={cn(card,"min-w-[210px] flex-1 p-4")}><div className="flex items-center justify-between"><div className="flex items-center gap-2"><div className="grid size-9 place-items-center rounded-full bg-white/[.06] text-xs font-bold text-violet-200">{asset.slice(0,2)}</div><div><p className="text-sm font-semibold">{asset}</p><p className="text-[11px] text-slate-500">{row?.symbol||"BRL"}</p></div></div>{status==="LIVE"?<Wifi className="size-4 text-emerald-400"/>:<WifiOff className="size-4 text-amber-400"/>}</div><p className="mt-4 text-xl font-semibold tabular-nums">{row?money(row.last):"Indisponível"}</p><div className="mt-2 flex justify-between text-[11px] text-slate-500"><span>Compra {row?money(row.ask):"—"}</span><span>Venda {row?money(row.bid):"—"}</span></div></div>}

function OrderCards({orders}:{orders:Order[]}){return <div className="divide-y divide-white/[.06] md:hidden">{orders.map((order,index)=><article className="p-4" key={`${order.created_at}-${index}`}><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className={cn("grid size-9 place-items-center rounded-xl",order.side==="BUY"?"bg-emerald-500/10 text-emerald-300":"bg-red-500/10 text-red-300")}>{order.side==="BUY"?<ArrowDownLeft className="size-4"/>:<ArrowUpRight className="size-4"/>}</div><div><p className="text-sm font-semibold">{order.side==="BUY"?"Compra":"Venda"} de {order.symbol.split("/")[0]}</p><p className="text-xs text-slate-500">{dateTime(order.created_at)}</p></div></div><Badge tone={order.side==="BUY"?"green":"red"}>{order.status==="FILLED"?"EXECUTADA":order.status}</Badge></div><div className="mt-4 grid grid-cols-3 gap-2 text-xs"><div><p className="text-slate-500">Quantidade</p><p className="mt-1 tabular-nums">{quantity(order.quantity,order.symbol)}</p></div><div><p className="text-slate-500">Preço</p><p className="mt-1 tabular-nums">{money(order.price)}</p></div><div className="text-right"><p className="text-slate-500">Taxa</p><p className="mt-1 tabular-nums">{money(order.fees)}</p></div></div></article>)}</div>}

