function CapitalGuide(){const rows=[["R$ 10","R$ 0,30","Não executa","Abaixo do mínimo interno"],["R$ 100","R$ 3,00","≈ R$ 0,01","Teste mínimo"],["R$ 500","R$ 15,00","≈ R$ 0,08","Métricas mais visíveis"],["R$ 1.000","R$ 30,00","≈ R$ 0,15","Recomendado para simulação"],["R$ 6.666,67","R$ 200,00","≈ R$ 1,00","Meta ilustrativa"]];return <section className={cn(card,"overflow-hidden")}><div className="border-b border-white/[.06] p-5 sm:px-6"><Badge tone="neutral">ESTIMATIVA EDUCACIONAL</Badge><h2 className="mt-3 text-lg font-semibold">Capital, tamanho da ordem e resultado provável</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-slate-400">Cenário ilustrativo: perfil conservador usando 3% do capital por ordem, alta favorável de 2% e custo total aproximado de 1,5% entre taxas, spread e execução.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="text-xs text-slate-500"><tr>{["Capital virtual","Ordem estimada","Líquido estimado","Leitura"].map(label=><th className="px-6 py-3 font-medium" key={label}>{label}</th>)}</tr></thead><tbody>{rows.map(row=><tr className="border-t border-white/[.06]" key={row[0]}>{row.map((value,index)=><td className={cn("px-6 py-4",index<3&&"tabular-nums",index===2&&"font-medium text-emerald-300")} key={value}>{value}</td>)}</tr>)}</tbody></table></div><p className="border-t border-white/[.06] px-6 py-4 text-xs leading-5 text-amber-200/80">Não existe valor que garanta lucro. Se a variação favorável não superar os custos, aumentar o capital apenas aumenta o prejuízo proporcional.</p></section>}

function BotWorkspace({active,capital,pending,error,onCapital,onReset,onAction}:{active:boolean;capital:string;pending:boolean;error?:string;onCapital:(value:string)=>void;onReset:()=>void;onAction:()=>void}){
  const profiles=[
    {key:"CONSERVATIVE" as const,name:"Conservador",trade:.03,asset:.10,exposure:.50,reserve:.30,daily:.02,drawdown:.08,description:"Prioriza proteção e ordens menores. Ideal para validar a estratégia por mais tempo."},
    {key:"MODERATE" as const,name:"Moderado",trade:.05,asset:.15,exposure:.60,reserve:.25,daily:.03,drawdown:.10,description:"Equilibra frequência, exposição e proteção. Bom para comparar resultados."},
    {key:"AGGRESSIVE" as const,name:"Agressivo",trade:.10,asset:.30,exposure:.80,reserve:.10,daily:.06,drawdown:.20,description:"Gera ordens maiores e oscilações mais fortes. Use somente no simulador."},
  ];
  const queryClient=useQueryClient(); const currentBot=queryClient.getQueryData<Bot[]>(["bots"])?.[0]; const profileDashboard=useQuery({queryKey:["dashboard",currentBot?.id],queryFn:()=>{if(!currentBot)throw new Error("Bot não encontrado");return api<Dashboard>(`/bots/${currentBot.id}/dashboard`)},enabled:Boolean(currentBot)}); const currentProfile=profileDashboard.data?.risk_profile?.name||"CONSERVATIVE";
  const profileChange=useMutation({mutationFn:(profile:RiskProfile["name"])=>{if(!currentBot)throw new Error("Bot não encontrado");return api<{profile:RiskProfile["name"]}>(`/bots/${currentBot.id}/paper-risk-profile`,{method:"PUT",body:JSON.stringify({profile})})},onSuccess:()=>queryClient.invalidateQueries({queryKey:["dashboard",currentBot?.id]})});
  return <div className="space-y-4"><section className="flex flex-wrap items-start justify-between gap-5"><div><Badge>LABORATÓRIO VIRTUAL</Badge><h1 className="mt-4 text-3xl font-semibold">Central do Bot</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-400">Configure e controle o Paper Bot. Ele lê o mercado real, mas todas as compras, vendas e resultados desta área são virtuais.</p></div><Badge tone={active?"green":"neutral"}>{active?"AUTOMAÇÃO ATIVA":"PAUSADO"}</Badge></section><section className={cn(card,"p-5 sm:p-6")}><h2 className="font-semibold">Comandos do simulador</h2><p className="mt-1 text-sm text-slate-500">Escolha o capital virtual antes de começar um novo teste.</p><div className="mt-5 flex flex-wrap items-end gap-3"><label className="w-48 text-xs font-medium text-slate-400">Capital inicial virtual (BRL)<Input className="mt-2 tabular-nums" type="number" min="10" max="1000000" step="10" value={capital} onChange={event=>onCapital(event.target.value)}/></label><Button variant="danger" disabled={pending||Number(capital)<10} onClick={onReset}><RotateCcw className="mr-2 size-4"/>Zerar e aplicar</Button><Button variant={active?"secondary":undefined} disabled={pending} onClick={onAction}>{active?<Pause className="mr-2 size-4"/>:<Play className="mr-2 size-4"/>}{active?"Pausar":"Iniciar automação"}</Button></div>{error&&<p role="alert" className="mt-4 text-sm text-red-300">{error}</p>}{profileChange.error&&<p role="alert" className="mt-4 text-sm text-red-300">{profileChange.error.message}</p>}{profileChange.data&&<p role="status" className="mt-4 text-sm text-emerald-300">Perfil {profileChange.data.profile==="AGGRESSIVE"?"Agressivo":profileChange.data.profile==="MODERATE"?"Moderado":"Conservador"} aplicado ao Paper Bot.</p>}</section><section><div className="mb-3"><h2 className="text-lg font-semibold">Perfis de risco do simulado</h2><p className="mt-1 text-sm text-slate-500">Pause o bot para trocar. Os valores são limites máximos, não metas nem garantia de lucro.</p></div><div className="grid gap-4 xl:grid-cols-3">{profiles.map(profile=>{const selected=currentProfile===profile.key;const currentOrder=Number(capital)*profile.trade;const exampleOrder=1000*profile.trade;return <article className={cn(card,"overflow-hidden border",selected&&"border-violet-400/50 ring-1 ring-violet-400/20")} key={profile.key}><div className="p-5"><div className="flex items-start justify-between gap-3"><div><Badge tone={profile.key==="AGGRESSIVE"?"amber":profile.key==="MODERATE"?"neutral":"green"}>{profile.name.toUpperCase()}</Badge><p className="mt-3 text-sm leading-6 text-slate-400">{profile.description}</p></div>{selected&&<Check className="size-5 shrink-0 text-violet-300"/>}</div><div className="mt-5 grid grid-cols-2 gap-3 text-xs"><div className="rounded-xl bg-black/20 p-3"><p className="text-slate-500">Por ordem</p><p className="mt-1 text-lg font-semibold">{profile.trade*100}%</p></div><div className="rounded-xl bg-black/20 p-3"><p className="text-slate-500">Por ativo</p><p className="mt-1 text-lg font-semibold">{profile.asset*100}%</p></div><div className="rounded-xl bg-black/20 p-3"><p className="text-slate-500">Exposição máx.</p><p className="mt-1 font-semibold">{profile.exposure*100}%</p></div><div className="rounded-xl bg-black/20 p-3"><p className="text-slate-500">Reserva</p><p className="mt-1 font-semibold">{profile.reserve*100}%</p></div><div className="rounded-xl bg-black/20 p-3"><p className="text-slate-500">Perda diária</p><p className="mt-1 font-semibold">{profile.daily*100}%</p></div><div className="rounded-xl bg-black/20 p-3"><p className="text-slate-500">Drawdown</p><p className="mt-1 font-semibold">{profile.drawdown*100}%</p></div></div></div><div className="border-t border-white/[.06] bg-black/15 p-5"><p className="text-xs text-slate-500">Com seu capital: <strong className="text-white">{money(currentOrder)} por ordem</strong></p><p className="mt-1 text-xs text-slate-500">Com R$ 1.000: ordem de {money(exampleOrder)} e líquido ilustrativo de {money(exampleOrder*.005)} numa alta de 2%.</p><p className="mt-1 text-xs text-slate-500">Capital mínimo para ordem de R$ 1: {money(1/profile.trade)}.</p><Button className="mt-4 w-full" variant={selected?"secondary":undefined} disabled={selected||active||pending||profileChange.isPending} onClick={()=>profileChange.mutate(profile.key)}>{selected?"Perfil atual":active?"Pause para selecionar":profileChange.isPending?"Aplicando…":"Selecionar perfil"}</Button></div></article>})}</div></section><section className="grid gap-3 md:grid-cols-3">{[["1. Observar","Lê preços e liquidez reais em BRL."],["2. Validar","Estratégia e barreiras de risco precisam concordar."],["3. Simular","Registra ordem, taxa e resultado sem movimentar dinheiro."]].map(([title,body])=><div className={cn(card,"p-5")} key={title}><p className="font-semibold text-violet-200">{title}</p><p className="mt-2 text-sm leading-6 text-slate-500">{body}</p></div>)}</section></div>
}

function DataWorkspace({data}:{data?:Dashboard}){const metrics=[["Capital inicial",data?.summary.initial_capital],["Patrimônio",data?.summary.equity],["Resultado",data?.summary.total_pnl],["Investido",data?.summary.invested]];return <div className="space-y-4"><section><Badge tone="neutral">LEITURA DO SIMULADOR</Badge><h1 className="mt-4 text-3xl font-semibold">Dados e métricas</h1><p className="mt-2 text-sm text-slate-400">Uma visão separada para entender preços, desempenho e custos antes de pensar em dinheiro real.</p></section><section className="flex gap-3 overflow-x-auto pb-2">{["BTC/BRL","ETH/BRL","SOL/BRL"].map(symbol=><MarketCard key={symbol} row={data?.market.find(row=>row.symbol===symbol)} status={data?.market_status||"UNAVAILABLE"}/>)}</section><section className="grid grid-cols-2 gap-3 lg:grid-cols-4">{metrics.map(([label,value])=><div className={cn(card,"p-5")} key={label}><p className="text-xs text-slate-500">{label}</p><p className="mt-3 text-xl font-semibold tabular-nums">{money(value)}</p></div>)}</section><CapitalGuide/><section className={cn(card,"overflow-hidden")}><div className="border-b border-white/[.06] p-5"><h2 className="font-semibold">Últimas operações simuladas</h2><p className="mt-1 text-sm text-slate-500">{data?.orders.length||0} registros recentes</p></div>{data?.orders.length?<OrderCards orders={data.orders}/>:<div className="p-10 text-center text-sm text-slate-500">Nenhuma operação registrada neste teste.</div>}</section></div>}

function SecurityWorkspace({connected}:{connected:boolean}){return <div className="space-y-4"><section><Badge tone="green">SEM DEPÓSITO NECESSÁRIO</Badge><h1 className="mt-4 text-3xl font-semibold">Segurança</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-400">Você pode desenvolver, testar estratégias e comparar métricas apenas com saldo virtual. Não é necessário colocar dinheiro agora.</p></section><section className={cn(card,"grid gap-4 p-6 md:grid-cols-3")}>{[["Paper Trading","Ativo e totalmente virtual",true],["Mercado Bitcoin",connected?"Conectado somente para leitura":"Não conectado",connected],["Executor real","Bloqueado no servidor",true]].map(([title,body,ok])=><div className="rounded-xl border border-white/[.06] bg-black/20 p-4" key={String(title)}><div className="flex items-center gap-2"><span className={cn("size-2 rounded-full",ok?"bg-emerald-400":"bg-amber-400")}/><p className="font-semibold">{String(title)}</p></div><p className="mt-2 text-sm text-slate-500">{String(body)}</p></div>)}</section><CapitalGuide/></div>}

function BotMonitorModal({data,stopping,onStop,onEmergency}:{data?:Dashboard;stopping:boolean;onStop:()=>void;onEmergency:()=>void}){
  const pnl=Number(data?.summary.total_pnl||0);
  const buys=data?.orders.filter(order=>order.side==="BUY").length||0;
  const sells=data?.orders.filter(order=>order.side==="SELL").length||0;
  const metrics=[
    ["Ganhos",money(Math.max(pnl,0)),ArrowUpRight,"text-emerald-300","bg-emerald-500/10"],
    ["Perdas",money(Math.abs(Math.min(pnl,0))),ArrowDownLeft,"text-red-300","bg-red-500/10"],
    ["Compras",String(buys),ArrowDownLeft,"text-cyan-300","bg-cyan-500/10"],
    ["Vendas",String(sells),ArrowUpRight,"text-violet-300","bg-violet-500/10"],
  ] as const;
  const marketLive=data?.market_status==="LIVE";
  const cycle=[
    [Radio,marketLive?"Cotações ao vivo":"Aguardando cotações",marketLive?"BTC, ETH e SOL recebidos":"Nenhuma decisão será executada sem dados",marketLive],
    [ShieldCheck,"Proteção aplicada","Limites e saldo verificados",true],
    [Activity,"Buscando oportunidade","Aguardando estratégia confirmar",false],
  ] as const;
  return <div className="fixed inset-0 z-50 grid items-start justify-items-center overflow-y-auto bg-[#050711]/90 p-3 backdrop-blur-xl sm:p-6" role="presentation">
    <section aria-labelledby="bot-monitor-title" aria-modal="true" className="relative w-full max-w-5xl overflow-hidden rounded-3xl border border-white/10 bg-[#0c111e] shadow-2xl" role="dialog">
      <header className="flex flex-wrap items-center justify-between gap-4 border-b border-white/[.07] p-5 sm:px-7 sm:py-6">
        <div>
          <div className="flex items-center gap-2"><span className="bitty-pulse size-2 rounded-full bg-emerald-400"/><Badge>BOT TRABALHANDO</Badge></div>
          <h2 className="mt-3 text-balance text-2xl font-semibold sm:text-3xl" id="bot-monitor-title">Central de operações do Bitty</h2>
          <p className="mt-1 text-pretty text-sm text-slate-400">Acompanhamento do simulador em tempo real, com decisões e proteção visíveis.</p>
        </div>
        <div className="flex flex-wrap gap-2"><Button variant="secondary" disabled={stopping} onClick={onStop}><Pause className="mr-2 size-4"/>{stopping?"Parando…":"Parar bot"}</Button><Button variant="danger" disabled={stopping} onClick={onEmergency}><ShieldCheck className="mr-2 size-4"/>Emergência</Button></div>
      </header>
      <div className="grid gap-4 p-4 sm:p-6 lg:grid-cols-[300px_1fr]">
        <aside className="relative overflow-hidden rounded-2xl border border-white/[.07] bg-[#090e19] p-5">
          <div className="flex items-center justify-between"><div><p className="text-xs font-medium text-slate-500">AGENTE DE MERCADO</p><p className="mt-1 font-semibold">Bitty</p></div><Badge tone="green">ONLINE</Badge></div>
          <div className="relative mx-auto mt-1 grid h-52 max-w-60 place-items-center">
            <div className="bitty-character-glow absolute size-36 rounded-full bg-cyan-400/15 blur-3xl"/>
            <div className="bitty-character-shadow absolute bottom-3 h-2 w-20 rounded-full bg-cyan-400/15 blur-md"/>
            <div className="bitty-character relative z-10 grid place-items-center"><Image alt="Bitty, o robô assistente de automação" className="h-52 w-48 object-contain" height={360} priority src="/images/bitty-bot.png" width={360}/></div>
          </div>
          <div className="rounded-xl border border-emerald-500/15 bg-emerald-500/[.05] p-4">
            <div className="flex items-center gap-2 text-sm font-medium text-emerald-300"><Radio className="size-4"/>Analisando o mercado agora</div>
            <p className="mt-2 text-pretty text-xs leading-5 text-slate-400">Estou comparando preço, taxas e risco antes de qualquer decisão simulada.</p>
          </div>
          <div className="mt-4 space-y-3">{cycle.map(([Icon,title,description,complete],index)=><div className="flex items-start gap-3" key={title}><span className={cn("mt-0.5 grid size-7 shrink-0 place-items-center rounded-lg",complete?"bg-emerald-500/10 text-emerald-300":"bg-white/[.05] text-slate-400")}><Icon className={cn("size-3.5",!complete&&"bitty-pulse")}/></span><div className="min-w-0"><p className="text-xs font-medium text-slate-200">{index+1}. {title}</p><p className="mt-0.5 text-[11px] text-slate-500">{description}</p></div></div>)}</div>
        </aside>
        <div className="space-y-4">
          <section className="grid grid-cols-2 gap-3">{metrics.map(([label,value,Icon,color,background])=><div className="rounded-2xl border border-white/[.07] bg-[#090e19] p-4" key={label}><div className="flex items-center justify-between"><p className="text-xs text-slate-500">{label}</p><span className={cn("grid size-8 place-items-center rounded-lg",background)}><Icon className={cn("size-4",color)}/></span></div><p className={cn("mt-3 text-xl font-semibold tabular-nums sm:text-2xl",color)}>{value}</p></div>)}</section>
          <section className="rounded-2xl border border-white/[.07] bg-[#090e19] p-5">
            <div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs text-slate-500">Patrimônio virtual</p><p className="mt-1 text-2xl font-semibold tabular-nums">{money(data?.summary.equity)}</p></div><Badge tone={data?.market_status==="LIVE"?"green":"amber"}>{data?.market_status==="LIVE"?"MERCADO AO VIVO":"AGUARDANDO DADOS"}</Badge></div>
            <div className="mt-5 border-t border-white/[.06] pt-4"><div className="mb-3 flex items-center justify-between"><p className="text-xs font-medium text-slate-300">Mercados monitorados</p><p className="text-[11px] text-slate-600">Atualização automática</p></div><div className="grid grid-cols-3 gap-2">{["BTC/BRL","ETH/BRL","SOL/BRL"].map(symbol=>{const row=data?.market?.find(item=>item.symbol===symbol);return <div className="rounded-xl border border-white/[.05] bg-white/[.025] p-3" key={symbol}><div className="flex items-center gap-2"><span className={cn("size-1.5 rounded-full",row?"bg-emerald-400":"bg-amber-400")}/><p className="text-xs font-medium">{symbol.split("/")[0]}</p></div><p className="mt-2 truncate text-xs tabular-nums text-slate-400">{row?money(row.last):"Sem cotação"}</p></div>})}</div></div>
          </section>
          <div className="flex items-center justify-center gap-2 rounded-xl border border-white/[.05] px-4 py-3 text-center text-xs text-slate-500"><ShieldCheck className="size-4 shrink-0 text-emerald-400"/>Use “Parar bot” para encerrar normalmente ou “Emergência” para bloquear novas ordens imediatamente.</div>
        </div>
      </div>
    </section>
  </div>
}

function DashboardScreen({bot}:{bot:Bot}){
  const queryClient=useQueryClient(); const syncState=useBotSync(bot.id); const [botMonitorOpen,setBotMonitorOpen]=useState(false); const dashboard=useQuery({queryKey:["dashboard",bot.id],queryFn:()=>api<Dashboard>(`/bots/${bot.id}/dashboard`),refetchInterval:botMonitorOpen?3000:5000}); const data=dashboard.data;
  const [tab,setTab]=useState<DashboardTab>("overview");
  const action=useMutation({mutationFn:(kind:string)=>api(`/bots/${bot.id}/${kind}`,{method:"POST"}),onSuccess:(_result,kind)=>{queryClient.invalidateQueries({queryKey:["bots"]});queryClient.invalidateQueries({queryKey:["dashboard"]});if(kind==="start")setBotMonitorOpen(true);if(kind==="stop"||kind==="emergency-stop")setBotMonitorOpen(false)}}); const logout=useMutation({mutationFn:()=>api("/auth/logout",{method:"POST"}),onSuccess:()=>{queryClient.clear();window.location.reload()}});
  const [paperCapitalOverride,setPaperCapital]=useState<string|null>(null); const paperCapital=paperCapitalOverride??(data?.summary.initial_capital?String(Number(data.summary.initial_capital)):"");
  const resetPaper=useMutation({mutationFn:()=>api<{reset:boolean;capital:string}>(`/bots/${bot.id}/reset-paper`,{method:"POST",body:JSON.stringify({initial_capital_brl:paperCapital})}),onSuccess:result=>{setPaperCapital(String(Number(result.capital)));queryClient.invalidateQueries({queryKey:["bots"]});queryClient.invalidateQueries({queryKey:["dashboard"]})}});
  const accounts=useQuery({queryKey:["exchange-accounts"],queryFn:()=>api<Array<{id:string;exchange:string;environment:string;connected:boolean}>>("/exchange-accounts")}); const readiness=useQuery({queryKey:["real-readiness",bot.id],queryFn:()=>api<{checks:Record<string,boolean>}>(`/bots/${bot.id}/real-readiness`)}); const [clientId,setClientId]=useState(""); const [clientSecret,setClientSecret]=useState(""); const [realCapital,setRealCapital]=useState("10"); const connect=useMutation({mutationFn:()=>api("/exchange-accounts/mercado-bitcoin",{method:"POST",body:JSON.stringify({client_id:clientId,client_secret:clientSecret})}),onSuccess:()=>{setClientId("");setClientSecret("");queryClient.invalidateQueries({queryKey:["exchange-accounts"]});queryClient.invalidateQueries({queryKey:["real-readiness"]})}}); const preflight=useMutation({mutationFn:()=>api<Preflight>(`/exchange-accounts/mercado-bitcoin/preflight/${bot.id}`,{method:"POST"})}); const saveRealCapital=useMutation({mutationFn:()=>api<{amount_brl:string}>(`/bots/${bot.id}/real-capital`,{method:"PUT",body:JSON.stringify({amount_brl:realCapital})}),onSuccess:result=>{setRealCapital(result.amount_brl);preflight.reset()}}); const mb=accounts.data?.find(account=>account.exchange==="MERCADO_BITCOIN"&&account.environment==="LIVE");
  const active=["ACTIVE","STARTING","RECONNECTING"].includes(bot.status); const metrics=[["Patrimônio",data?.summary.equity,WalletCards],["Resultado",data?.summary.total_pnl,Activity],["Disponível",data?.summary.available,CircleDollarSign],["Investido",data?.summary.invested,BarChart3]] as const; const markets=["BTC/BRL","ETH/BRL","SOL/BRL"].map(symbol=>data?.market?.find(row=>row.symbol===symbol)); const curve=data?.equity_curve?.map(point=>({time:new Date(point.time).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}),equity:Number(point.equity)}))||[];
  return <main className="min-h-dvh bg-[#080b16] pb-20 lg:grid lg:grid-cols-[230px_1fr] lg:pb-0"><aside className="hidden border-r border-white/[.06] bg-[#0b0f1a] p-5 lg:flex lg:flex-col"><Logo/><nav className="mt-10 space-y-1">{navigation.map(([value,Icon,label])=><button key={value} onClick={()=>setTab(value)} className={cn("flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm transition",tab===value?"bg-violet-500/10 font-medium text-violet-200":"text-slate-500 hover:bg-white/[.04] hover:text-slate-300")}><Icon className="size-4"/>{label}</button>)}</nav><div className="mt-auto rounded-2xl border border-emerald-500/15 bg-emerald-500/[.06] p-4"><div className="flex items-center gap-2 text-sm font-medium"><ShieldCheck className="size-4 text-emerald-400"/> Proteção ativa</div><p className="mt-2 text-xs leading-5 text-slate-500">Sem dados confiáveis, o Bitty não opera.</p></div></aside>
    <div className="min-w-0"><header className="sticky top-0 z-20 flex min-h-20 items-center justify-between border-b border-white/[.06] bg-[#080b16]/85 px-5 backdrop-blur-xl sm:px-8"><div className="lg:hidden"><Logo/></div><div className="hidden lg:block"><p className="text-xs text-slate-500">PAINEL PRINCIPAL</p><p className="mt-1 font-semibold">{bot.name}</p></div><div className="flex items-center gap-2"><Badge tone={syncState==="live"?"green":"neutral"}><Radio className="mr-1 size-3"/>{syncState==="live"?"SINCRONIZADO":syncState==="reconnecting"?"RECONECTANDO":"ATUALIZAÇÃO AUTOMÁTICA"}</Badge><Badge tone={data?.market_status==="LIVE"?"green":"amber"}>{data?.market_status==="LIVE"?"MERCADO AO VIVO":"SEM COTAÇÃO"}</Badge><button aria-label="Sair" onClick={()=>logout.mutate()} className="grid size-10 place-items-center rounded-xl text-slate-500 hover:bg-white/[.05] hover:text-white"><LogOut className="size-4"/></button></div></header>
    <div className="mx-auto max-w-[1400px] p-5 sm:p-8">{tab==="bot"&&<BotWorkspace active={active} capital={paperCapital} pending={action.isPending||resetPaper.isPending} error={action.error?.message||resetPaper.error?.message} onCapital={setPaperCapital} onReset={()=>{if(window.confirm(`Zerar histórico, posições, gráfico e resultado e reiniciar o teste com ${money(paperCapital)} virtuais?`))resetPaper.mutate()}} onAction={()=>action.mutate(active?"pause":"start")}/>} {tab==="data"&&<DataWorkspace data={data}/>} {tab==="security"&&<SecurityWorkspace connected={Boolean(mb)}/>}<div className={tab==="overview"?"block":"hidden"}><section className="flex flex-wrap items-end justify-between gap-5"><div><div className="flex flex-wrap items-center gap-3"><h1 className="text-3xl font-semibold tracking-tight sm:text-4xl">Olá, aqui é o seu Bitty.</h1><Badge tone={active?"green":"neutral"}>{active?"AUTOMAÇÃO ATIVA":"PAUSADO"}</Badge></div><p className="mt-2 text-sm text-slate-400">Preços em reais, decisões registradas e risco sempre visível.</p></div><div className="flex flex-wrap items-end gap-2"><label className="w-40 text-xs font-medium text-slate-400">Capital do teste (BRL)<Input className="mt-1.5 tabular-nums" aria-label="Capital inicial do teste" type="number" min="10" max="1000000" step="10" value={paperCapital} onChange={event=>setPaperCapital(event.target.value)}/></label><Button variant="danger" disabled={resetPaper.isPending||Number(paperCapital)<10||Number(paperCapital)>1000000} onClick={()=>{if(window.confirm(`Zerar histórico, posições, gráfico e resultado e reiniciar o teste com ${money(paperCapital)} virtuais?`))resetPaper.mutate()}}><RotateCcw className="mr-2 size-4"/>{resetPaper.isPending?"Zerando…":"Zerar e aplicar"}</Button>{active?<Button variant="secondary" disabled={action.isPending} onClick={()=>action.mutate("pause")}><Pause className="mr-2 size-4"/>Pausar</Button>:<Button disabled={action.isPending} onClick={()=>action.mutate("start")}><Play className="mr-2 size-4"/>Iniciar automação</Button>}</div></section>{(action.error||resetPaper.error)&&<div role="alert" className="mt-4 rounded-xl border border-red-500/20 bg-red-500/10 p-3 text-sm text-red-300">{action.error?.message||resetPaper.error?.message}</div>}
    <section className="mt-7 flex gap-3 overflow-x-auto pb-2">{markets.map((row,index)=><MarketCard key={row?.symbol||index} row={row} status={data?.market_status||"UNAVAILABLE"}/>)}</section>
    <section className="mt-3 grid grid-cols-2 gap-3 xl:grid-cols-4">{metrics.map(([label,value,Icon])=><div key={label} className={cn(card,"p-4 sm:p-5")}><div className="flex items-center justify-between"><p className="text-xs text-slate-500 sm:text-sm">{label}</p><Icon className="size-4 text-slate-600"/></div><p className={cn("mt-3 text-xl font-semibold tabular-nums sm:text-2xl",label==="Resultado"&&Number(value)>=0&&"text-emerald-300",label==="Resultado"&&Number(value)<0&&"text-red-300")}>{money(value)}</p></div>)}</section>
    <section className="mt-4 grid gap-4 xl:grid-cols-[1.65fr_1fr]"><div className={cn(card,"p-5 sm:p-6")}><div className="flex items-center justify-between"><div><h2 className="font-semibold">Patrimônio</h2><p className="mt-1 text-sm text-slate-500">Evolução registrada pelo motor</p></div><Badge tone="neutral">BRL</Badge></div><div className="mt-6 h-64">{curve.length?<ResponsiveContainer><AreaChart data={curve}><defs><linearGradient id="equity" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b5cf6" stopOpacity=".35"/><stop offset="100%" stopColor="#8b5cf6" stopOpacity="0"/></linearGradient></defs><CartesianGrid stroke="#202637" vertical={false}/><XAxis dataKey="time" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false}/><YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} width={48} domain={["auto","auto"]} tickFormatter={value=>`R$ ${Number(value).toFixed(0)}`}/><Tooltip contentStyle={{background:"#101522",border:"1px solid #293148",borderRadius:12}} formatter={value=>money(String(value))}/><Area dataKey="equity" type="monotone" stroke="#a78bfa" fill="url(#equity)" strokeWidth={2.5}/></AreaChart></ResponsiveContainer>:<div className="grid h-full place-items-center text-sm text-slate-500">Aguardando o primeiro registro.</div>}</div></div><div className={cn(card,"p-5 sm:p-6")}><div className="flex items-center justify-between"><div><h2 className="font-semibold">Barreiras de segurança</h2><p className="mt-1 text-sm text-slate-500">Aplicadas antes de cada ordem</p></div><ShieldCheck className="size-5 text-violet-300"/></div><ul className="mt-6 space-y-4">{["30% do capital em reserva","Limite diário de perda","Circuit breaker de drawdown","Bloqueio de cotação antiga","Identificador único por ordem"].map(item=><li className="flex items-center gap-3 text-sm text-slate-300" key={item}><span className="grid size-5 place-items-center rounded-full bg-emerald-500/10"><Check className="size-3 text-emerald-400"/></span>{item}</li>)}</ul></div></section>
    <section className={cn(card,"mt-4 overflow-hidden")}><div className="flex items-center justify-between border-b border-white/[.06] p-5 sm:px-6"><div><h2 className="font-semibold">Atividade recente</h2><p className="mt-1 text-sm text-slate-500">Compras e vendas simuladas, com valores formatados</p></div><Clock3 className="size-5 text-slate-600"/></div>{data?.orders.length?<><OrderCards orders={data.orders}/><div className="hidden overflow-x-auto md:block"><table className="w-full text-left text-sm"><thead className="text-xs text-slate-500"><tr>{["Data","Ativo","Operação","Status","Quantidade","Preço unitário","Taxa"].map(label=><th className="px-6 py-3 font-medium" key={label}>{label}</th>)}</tr></thead><tbody>{data.orders.map((order,index)=><tr className="border-t border-white/[.06]" key={`${order.created_at}-${index}`}><td className="whitespace-nowrap px-6 py-4 text-slate-400">{dateTime(order.created_at)}</td><td className="px-6 py-4 font-medium">{order.symbol}</td><td className="px-6 py-4"><Badge tone={order.side==="BUY"?"green":"red"}>{order.side==="BUY"?"COMPRA":"VENDA"}</Badge></td><td className="px-6 py-4 text-slate-300">{order.status==="FILLED"?"Executada":order.status}</td><td className="px-6 py-4 tabular-nums">{quantity(order.quantity,order.symbol)}</td><td className="whitespace-nowrap px-6 py-4 tabular-nums">{money(order.price)}</td><td className="whitespace-nowrap px-6 py-4 tabular-nums text-slate-400">{money(order.fees)}</td></tr>)}</tbody></table></div></>:<div className="px-6 py-8"><div className="text-center"><History className="mx-auto size-8 text-slate-700"/><p className="mt-3 font-medium">Nenhuma ordem ainda</p><p className="mt-1 text-sm text-slate-500">O motor está analisando; abaixo estão as decisões mais recentes.</p></div><div className="mx-auto mt-5 grid max-w-3xl gap-2">{data?.signals?.slice(0,3).map(signal=><div className="flex flex-wrap items-center gap-3 rounded-xl border border-white/[.06] bg-black/15 px-4 py-3 text-sm" key={`${signal.symbol}-${signal.timestamp}`}><span className="font-semibold">{signal.symbol}</span><Badge tone={signal.action==="BUY"?"green":signal.action==="SELL"?"red":"neutral"}>{signal.action==="BUY"?"COMPRA":signal.action==="SELL"?"VENDA":"AGUARDAR"}</Badge><span className="min-w-0 flex-1 text-slate-400">{signal.outcome}</span><span className="text-xs text-slate-600">{dateTime(signal.timestamp)}</span></div>)}</div></div>}</section>
    <section className="mt-4 rounded-2xl border border-amber-500/15 bg-amber-500/[.045] p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><Badge tone="amber">DINHEIRO REAL BLOQUEADO</Badge><h2 className="mt-3 text-lg font-semibold">Conexão com o Mercado Bitcoin</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-slate-400">A validação consulta conta, saldo, regras e taxas. Não cria ordens. Use uma chave exclusiva, sem qualquer permissão de saque.</p></div><LockKeyhole className="size-6 text-amber-400"/></div>{mb?<div className="mt-5"><div className="flex flex-wrap items-center gap-3"><Badge tone="green">CONECTADO</Badge><span className="text-sm text-slate-400">Conta validada em modo somente leitura.</span><Button variant="secondary" disabled={preflight.isPending} onClick={()=>preflight.mutate()}>{preflight.isPending?"Verificando…":"Executar diagnóstico seguro"}</Button></div><div className="mt-4 flex flex-wrap items-end gap-3 rounded-xl border border-white/[.07] bg-black/15 p-4"><label className="min-w-[180px] text-xs font-medium text-slate-400">Limite inicial real (BRL)<Input className="mt-2" aria-label="Limite inicial real" type="number" min="10" max="1000" step="0.01" value={realCapital} onChange={event=>setRealCapital(event.target.value)}/></label><Button disabled={saveRealCapital.isPending||Number(realCapital)<10||Number(realCapital)>1000} onClick={()=>saveRealCapital.mutate()}>{saveRealCapital.isPending?"Salvando…":"Salvar limite"}</Button><p className="max-w-md text-xs leading-5 text-slate-500">Define apenas o teto do modo real. Não transfere dinheiro e não envia ordens.</p></div>{saveRealCapital.error&&<div role="alert" className="mt-3 rounded-xl border border-red-500/20 bg-red-500/10 p-3 text-sm text-red-300">{saveRealCapital.error.message}</div>}{saveRealCapital.data&&<div className="mt-3 rounded-xl border border-emerald-500/20 bg-emerald-500/10 p-3 text-sm text-emerald-300">Limite real salvo em {money(saveRealCapital.data.amount_brl)}. Nenhum dinheiro foi movimentado.</div>}{preflight.error&&<div role="alert" className="mt-3 rounded-xl border border-red-500/20 bg-red-500/10 p-3 text-sm text-red-300">{preflight.error.message}</div>}{preflight.data&&<div className="mt-5 rounded-2xl border border-white/[.08] bg-black/20 p-4"><div className="grid gap-3 sm:grid-cols-3"><div><p className="text-xs text-slate-500">Saldo disponível no MB</p><p className="mt-1 font-semibold tabular-nums">{money(preflight.data.account.available_brl)}</p></div><div><p className="text-xs text-slate-500">Limite inicial real</p><p className="mt-1 font-semibold tabular-nums">{money(preflight.data.configured_capital)}</p></div><div><p className="text-xs text-slate-500">Ordens abertas</p><p className="mt-1 font-semibold tabular-nums">{preflight.data.open_orders}</p></div></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{[["Credenciais válidas",preflight.data.checks.credentials_valid],["Conta acessível",preflight.data.checks.account_readable],["Saldo cobre o limite",preflight.data.checks.balance_covers_capital],["Sem ordens abertas",preflight.data.checks.no_open_orders],["Bot Paper parado",preflight.data.checks.paper_bot_stopped],["Executor real bloqueado",!preflight.data.checks.live_executor_enabled]].map(([label,ok])=><div className={cn("flex items-center gap-2 text-sm",ok?"text-emerald-300":"text-amber-300")} key={String(label)}><span className={cn("grid size-5 place-items-center rounded-full",ok?"bg-emerald-500/10":"bg-amber-500/10")}>{ok&&<Check className="size-3"/>}</span>{String(label)}</div>)}</div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[620px] text-left text-xs"><thead className="text-slate-500"><tr>{["Ativo","Preço","Spread","Mínimo","Maker","Taker"].map(label=><th className="py-2 pr-4 font-medium" key={label}>{label}</th>)}</tr></thead><tbody>{preflight.data.markets.map(row=><tr className="border-t border-white/[.06]" key={row.symbol}><td className="py-3 pr-4 font-semibold">{row.symbol}</td><td className="py-3 pr-4">{money(row.last)}</td><td className="py-3 pr-4">{Number(row.spread_pct).toLocaleString("pt-BR",{maximumFractionDigits:4})}%</td><td className="py-3 pr-4">{money(row.min_cost)}</td><td className="py-3 pr-4">{(Number(row.maker_fee)*100).toLocaleString("pt-BR",{maximumFractionDigits:4})}%</td><td className="py-3">{(Number(row.taker_fee)*100).toLocaleString("pt-BR",{maximumFractionDigits:4})}%</td></tr>)}</tbody></table></div><div className="mt-4 space-y-1 border-t border-white/[.06] pt-4 text-xs text-amber-200/80">{preflight.data.blockers.map(item=><p key={item}>• {item}</p>)}</div><p className="mt-3 text-xs font-semibold text-slate-400">Diagnóstico somente leitura: {preflight.data.executed_orders} ordens enviadas.</p></div>}</div>:<div className="mt-5 grid gap-3 md:grid-cols-[1fr_1fr_auto]"><Input aria-label="Client ID" value={clientId} onChange={event=>setClientId(event.target.value)} placeholder="Client ID" autoComplete="off"/><Input aria-label="Client Secret" type="password" value={clientSecret} onChange={event=>setClientSecret(event.target.value)} placeholder="Client Secret" autoComplete="new-password"/><Button disabled={connect.isPending||clientId.length<8||clientSecret.length<8} onClick={()=>connect.mutate()}>{connect.isPending?"Validando…":"Conectar"}</Button></div>}{connect.error&&<div role="alert" className="mt-3 rounded-xl border border-red-500/20 bg-red-500/10 p-3 text-sm text-red-300">{connect.error.message}</div>}<div className="mt-5 grid gap-2 border-t border-amber-500/10 pt-4 text-sm sm:grid-cols-4"><span className={readiness.data?.checks.encryption_configured?"text-emerald-300":"text-slate-500"}>1. Criptografia</span><span className={readiness.data?.checks.mercado_bitcoin_connected?"text-emerald-300":"text-slate-500"}>2. Conta validada</span><span className={preflight.data?"text-emerald-300":"text-slate-500"}>3. Diagnóstico seguro</span><span className="text-slate-500">4. Executor real bloqueado</span></div></section><p className="py-6 text-center text-xs text-slate-600">{data?.disclaimer||"Resultados simulados não garantem resultados futuros."}</p></div></div></div>
    <nav className="safe-bottom fixed inset-x-0 bottom-0 z-30 grid grid-cols-4 border-t border-white/[.08] bg-[#0b0f1a]/95 px-2 pt-2 backdrop-blur-xl lg:hidden">{navigation.map(([value,Icon,label])=><button key={value} onClick={()=>setTab(value)} className={cn("flex min-h-12 flex-col items-center justify-center gap-1 text-[10px]",tab===value?"text-violet-300":"text-slate-500")}><Icon className="size-4"/>{label}</button>)}</nav>
    {botMonitorOpen&&<BotMonitorModal data={data} stopping={action.isPending} onStop={()=>action.mutate("stop")} onEmergency={()=>action.mutate("emergency-stop")}/>}
  </main>;
}

export default function Home(){const me=useQuery({queryKey:["me"],queryFn:()=>api<{email:string}>("/auth/me"),retry:false});const bots=useQuery({queryKey:["bots"],queryFn:()=>api<Bot[]>("/bots"),enabled:Boolean(me.data),refetchInterval:5000});if(me.isLoading)return <main className="grid min-h-dvh place-items-center bg-[#080b16]"><div className="size-9 animate-spin rounded-full border-2 border-violet-400 border-t-transparent"/></main>;if(!me.data)return <AuthScreen/>;if(bots.isLoading)return <main className="grid min-h-dvh place-items-center bg-[#080b16] text-sm text-slate-500">Carregando o Bitty…</main>;if(!bots.data?.[0])return <Onboarding/>;return <DashboardScreen bot={bots.data[0]}/>;}
